<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\LiveDisplaySessionService;
Auth::requireAdmin();$pdo=Database::connection();$sessionId=(int)($_POST['session_id']??0);$test=($_POST['data_mode']??'real')==='test';$target=($test?'test-index.php':'index.php').'?festival_session='.$sessionId;
if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid request.');}
try{$session=LiveDisplaySessionService::byId($pdo,$sessionId,$test);if(!$session||empty($session['group_name']))throw new RuntimeException('Festival projection was not found.');if(($_POST['action']??'')==='remove'){$pdo->prepare("UPDATE bdc_live_display_sessions SET holding_background_url=NULL,screen_type='holding',playlist_enabled=0,playlist_position=0,state_version=state_version+1,updated_by=:u,updated_at=NOW() WHERE id=:s")->execute(['u'=>(int)(Auth::user()['id']??0)?:null,'s'=>$sessionId]);$_SESSION['festival_projection_notice']='Custom Holding Screen background removed.';}else{$file=$_FILES['background']??null;if(!$file||empty($file['tmp_name'])||!is_uploaded_file($file['tmp_name']))throw new RuntimeException('Choose a Holding Screen image first.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime])||(int)$file['size']>12*1024*1024)throw new RuntimeException('Background must be JPG, PNG or WebP and no larger than 12 MB.');$size=getimagesize($file['tmp_name']);if(!$size||$size[0]<1280||$size[1]<720)throw new RuntimeException('Use a background at least 1280 × 720 pixels.');$dir=dirname(__DIR__,2).'/uploads/live-display';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('Holding Screen upload folder is unavailable.');$name='holding-'.$sessionId.'-'.bin2hex(random_bytes(6)).'.'.$types[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Holding Screen upload failed.');$url=url('uploads/live-display/'.$name);$pdo->prepare("UPDATE bdc_live_display_sessions SET holding_background_url=:url,screen_type='holding',playlist_enabled=0,playlist_position=0,state_version=state_version+1,updated_by=:u,updated_at=NOW() WHERE id=:s")->execute(['url'=>$url,'u'=>(int)(Auth::user()['id']??0)?:null,'s'=>$sessionId]);$_SESSION['festival_projection_notice']='Custom Holding Screen background saved and sent to the projector.';}}catch(Throwable $e){$_SESSION['festival_projection_error']=$e->getMessage();}header('Location: '.$target,true,303);exit;
